// contractSatSpillState refuses while answering what
// State actually found — whatever the failed lookup left behind.
//
// Every refusal the wardrobe mints elsewhere arrives with the zero value
// beside it, and the value a failed read is supposed to answer is usually the
// zero. So the defect and the claim agree, and a law about what an error must
// coincide with has nothing that can disagree with it.
type contractSatSpillState struct{ workflow.Contract }

func (m contractSatSpillState) State(p0 context.Context, p1 string) (string, error) {
	out, err := m.Contract.State(p0, p1)
	if err != nil {
		return out, err
	}
	return out, errors.New("contract: saturation spilled a found value into a refusal")
}

// contractSatPassthroughState answers State's
// argument verbatim, where the method's whole job was to change it.
//
// Every other wear answers something the subject did not — a zero, a stale
// repeat, a wrong count. A claim about what a transformation *removes*
// survives all of them, because a zero has had everything removed and passes
// trivially. The escaper that escapes nothing is spelled only by answering
// the input.
type contractSatPassthroughState struct{ workflow.Contract }

func (m contractSatPassthroughState) State(p0 context.Context, p1 string) (string, error) {
	if _, err := m.Contract.State(p0, p1); err != nil {
		var zero string
		return zero, err
	}
	return p1, nil
}

// contractSatFlapState alternates the fixture pair where
