type contractSatFlapState struct {
	workflow.Contract
	flip atomic.Int64
	a, b string
}

func (m *contractSatFlapState) State(_ context.Context, _ string) (string, error) {
	if m.flip.Add(1)%2 == 0 {
		return m.a, nil
	}
	return m.b, nil
}

